/* src/styles/6-components/inverse-surface.css */
/**
 * Inverse Surface — 짙은 면 위에 올라가는 부품의 색을 한꺼번에 바꾼다
 *
 * 카탈로그 부품(tab·btn·링크·초점 링)은 의미 토큰을 읽는다. 이 블록은 부품을 덮어쓰지 않고
 * 블록 안에서 의미 토큰이 가리키는 값을 밝은 단계로 바꾼다. 면의 색은 --surface로 받는다.
 *   <section class="section section--intro inverse-surface">…</section>
 *   <div class="inverse-surface" style="--surface: var(--color-gray-90)">…</div>
 * 근거: design-intelligence.md §5-2 「짙은 면이 시작되면 그 안의 부품도 바꾼다」
 * 레이어 밖에 둔다 — 블록 카탈로그(cover·link-rows)의 면 색과 같은 층에서 겨룬다.
 */
.inverse-surface {
  --color-text: var(--color-gray-0);
  --color-text-bolder: var(--color-gray-0);
  --color-text-subtle: var(--color-primary-10);
  --color-text-primary: var(--color-primary-20);
  --color-text-inverse: var(--color-primary-90);
  --color-primary: var(--color-primary-20);
  --color-link: var(--color-gray-0);
  --color-link-hover: var(--color-primary-20);
  --color-link-pressed: var(--color-primary-10);
  --color-link-visited: var(--color-gray-0);
  --color-point: var(--color-point-30);
  --color-border: var(--color-primary-60);
  --color-border-light: var(--color-primary-70);
  --color-border-primary: var(--color-primary-20);
  --color-button-primary-fill: var(--color-gray-0);
  --color-button-primary-fill-hover: var(--color-primary-10);
  --color-button-primary-fill-pressed: var(--color-primary-20);

  @apply bg-[var(--surface,var(--color-primary-80))] text-[var(--color-text)];
}

/* src/styles/6-components/link-rows.css */
/**
 * Link Rows — 링크 묶음을 가로 줄로 (블록 카탈로그 link-rows · design-intelligence §6-5)
 *   왼쪽에 섹션 제목(문장형), 오른쪽에 「묶음 이름 + 링크들」 줄 목록. 「소제목 + 밑줄 + 링크 세 개」 3열 묶음의 대안이다.
 *   색은 의미 토큰만 읽는다 — 짙은 면(inverse-surface)과 밝은 면 어느 쪽에도 놓인다.
 *   정본: src/blocks/link-rows/. MCP get_block("link-rows")
 *   <div class="container link-rows">
 *     <h2 class="link-rows__title" id="link-rows-title">…</h2>
 *     <dl class="link-rows__list">
 *       <div class="link-rows__row">
 *         <dt class="link-rows__group">…</dt>
 *         <dd class="link-rows__links"><a class="link-rows__link" href="…">…</a></dd>
 *       </div>
 *     </dl>
 *   </div>
 * 레이어 밖에 둔다 — inverse-surface와 같은 층.
 */
.link-rows {
  @apply grid gap-[3.2rem] laptop:gap-[6.4rem] laptop:[grid-template-columns:minmax(0,5fr)_minmax(0,7fr)];
}

/* KRDS heading-large(mobile 2.4 / pc 3.2rem) */
.link-rows__title {
  @apply m-0 max-w-[11em] [font-family:var(--font-heading)] text-[2.4rem] font-semibold leading-[1.5] tracking-[0.1rem] text-[var(--color-text-bolder)] [word-break:keep-all] tablet:text-[3.2rem];
}

.link-rows__list {
  @apply m-0 min-w-0 border-b border-[var(--color-border)];
}

.link-rows__row {
  @apply grid gap-y-[0.8rem] gap-x-[2.4rem] py-[2rem] border-t border-[var(--color-border)] tablet:[grid-template-columns:10rem_minmax(0,1fr)];
}

.link-rows__group {
  @apply m-0 text-[1.5rem] font-bold leading-[1.7] text-[var(--color-text-subtle)] [word-break:keep-all] tablet:pt-[0.8rem];
}

.link-rows__links {
  @apply flex flex-wrap gap-x-[3.2rem] gap-y-[0.4rem] m-0;
}

.link-rows__link {
  @apply inline-flex items-center min-h-[4.4rem] text-[1.9rem] font-bold leading-[1.5] text-[var(--color-text)] no-underline [word-break:keep-all] [text-underline-offset:0.4rem] hover:underline hover:text-[var(--color-link-hover)];
}

.link-rows__link:visited {
  @apply text-[var(--color-text)];
}
